-- mod-lan: Stratholme for the adventure route. Every mob in Stratholme drops the Key to the City (12382) for
-- players who don't have it, not only Magistrate Barthilas (his own drop stays), so the Service Entrance and the
-- city gates on the way to Baron Rivendare open.
-- The loot ids are those of the creatures spawned on map 329; the map condition keeps the drop inside
-- Stratholme for creatures that also stand elsewhere.

DELETE FROM `creature_loot_template` WHERE `Item` = 12382 AND `Entry` IN (10381, 10382, 10384, 10385, 10390, 10391, 10393, 10398, 10399, 10400, 10405, 10406, 10407, 10408, 10409, 10411, 10412, 10413, 10414, 10416, 10417, 10418, 10419, 10420, 10421, 10422, 10423, 10424, 10425, 10426, 10436, 10437, 10438, 10440, 10463, 10464, 10516, 10558, 10808, 10809, 10811, 10997, 11032, 11043, 11082, 14684);

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 1 AND `SourceEntry` = 12382 AND `SourceGroup` IN (10381, 10382, 10384, 10385, 10390, 10391, 10393, 10398, 10399, 10400, 10405, 10406, 10407, 10408, 10409, 10411, 10412, 10413, 10414, 10416, 10417, 10418, 10419, 10420, 10421, 10422, 10423, 10424, 10425, 10426, 10436, 10437, 10438, 10440, 10463, 10464, 10516, 10558, 10808, 10809, 10811, 10997, 11032, 11043, 11082, 14684);
